/** Physical private files, actual Spring/JPA completion boundaries and isolated PostgreSQL.
 * No fake owner is attached to unregistered bytes; no real account/provider is used. */
class PrivacyOrphanFilesIT {
    @TempDir Path temporary;private static RealPostgres database;private ServletWebServerApplicationContext app;private JdbcTemplate sql;private Path storage,operations,journalPath;private String[] args;
    private static final byte[] BYTES="%PDF-1.7\nSynthetic orphan evidence\n%%EOF".getBytes(java.nio.charset.StandardCharsets.US_ASCII);
    private static final String PASSWORD="Synthetic orphan recovery test password 2026";
    record Gate(CountDownLatch entered,CountDownLatch release,AtomicReference<UUID> file){}
    static class TestStorage extends PrivateFileStorage {
        final AtomicReference<Gate> gate=new AtomicReference<>();final AtomicBoolean failErase=new AtomicBoolean();TestStorage(StorageSettings settings){super(settings);}
        @Override public void put(String key,byte[] data)throws IOException {super.put(key,data);var current=gate.get();if(current!=null){current.file().set(UUID.fromString(key));current.entered().countDown();try{if(!current.release().await(15,TimeUnit.SECONDS))throw new IOException("Synthetic upload gate timeout.");}catch(InterruptedException stopped){Thread.currentThread().interrupt();throw new IOException("Synthetic upload interrupted.");}}}
        @Override public void eraseVerified(String key)throws IOException {if(failErase.get())throw new IOException("Synthetic physical cleanup failure.");super.eraseVerified(key);}
    }
    @TestConfiguration static class StorageConfig {@Bean @Primary TestStorage testPrivateStorage(StorageSettings settings){return new TestStorage(settings);}}
    @BeforeAll static void database(){database=new RealPostgres();}
    @AfterAll static void databaseClose(){if(database!=null)database.close();}
    @AfterEach void close(){if(app!=null){app.close();app=null;}}
    @BeforeEach void setup()throws Exception {
        database.resetSchema();storage=temporary.resolve("files");operations=temporary.resolve("ops");journalPath=temporary.resolve("journal");var values=new ArrayList<>(List.of(AuthTestSettings.arguments(database.apiConnectionUrl())));values.addAll(List.of("--STORAGE_PATH="+storage,"--FRONTEND_PATH="+temporary.resolve("public"),"--PRIVACY_OPERATIONS_ROOT="+operations,"--PRIVACY_ERASURE_JOURNAL_PATH="+journalPath,"--DEV_MAIL_PATH="+temporary.resolve("mail")));args=values.toArray(String[]::new);
        var env=new MockEnvironment();for(String arg:args){int at=arg.indexOf('=');env.withProperty(arg.substring(2,at),arg.substring(at+1));}var json=new ObjectMapper();var crypto=new CryptoService();var auth=new AuthSettings(env);var files=new StorageSettings(env);new PrivacyBackupCatalog(new PrivacyOperationsSettings(env,files),new PrivacySettings(env),new PrivacySigningKeys(env,auth,crypto,json),json,Clock.systemUTC()).initialize();start();
    }
    private void start(){app=(ServletWebServerApplicationContext)new SpringApplicationBuilder(UniCaronaApplication.class,StorageConfig.class).run(args);sql=app.getBean(JdbcTemplate.class);}
    private static String sha(byte[] bytes)throws Exception {return HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));}
    private UUID orphan()throws Exception {UUID file=UUID.randomUUID();app.getBean(PrivateFileStorage.class).put(file.toString(),BYTES);return file;}
    private PrivacyOrphanFileTransactions tx(){return app.getBean(PrivacyOrphanFileTransactions.class);}
    private void age(UUID file){sql.update("UPDATE privacy_orphan_file_observations SET first_seen_at=now()-interval '2 days',last_seen_at=now()-interval '2 days' WHERE file_id=?",file);}
    private PrivacyErasureJournal journal(){return app.getBean(PrivacyErasureJournal.class);}
    private void guard()throws Exception {app.getBean(PrivacyRestoreGuard.class).run(new DefaultApplicationArguments());}
    private Actor owner(){String hash=app.getBean(CryptoService.class).hashPassword(PASSWORD);UUID id=sql.queryForObject("INSERT INTO users(email,password_hash,name,birth_date,email_verified_at) VALUES(?,?,'Synthetic orphan test owner','2000-01-01',now()) RETURNING id",UUID.class,UUID.randomUUID()+"@example.test",hash);return new Actor(id,"user","active",null,null,null,true,Set.of());}
    private void metadata(UUID file,Actor owner)throws Exception {sql.update("INSERT INTO stored_files(id,owner_id,purpose,storage_key,content_type,byte_size,sha256) VALUES(?,?,'identity',?,'application/pdf',?,?)",file,owner.id(),file.toString(),BYTES.length,sha(BYTES));}
    @Test void twoStableObservationsPrecedeDurableSuppressionWithoutInventingAnOwner()throws Exception {
        UUID file=orphan();Files.setLastModifiedTime(storage.resolve(file.toString()),java.nio.file.attribute.FileTime.from(Instant.now().minus(Duration.ofDays(40))));int users=sql.queryForObject("SELECT count(*) FROM users",Integer.class);
        assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));assertEquals(PrivacyOrphanFileTransactions.Outcome.WAITING,tx().inspect(file));assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());age(file);assertEquals(PrivacyOrphanFileTransactions.Outcome.ERASED,tx().inspect(file));assertFalse(Files.exists(storage.resolve(file.toString())));assertEquals(users,sql.queryForObject("SELECT count(*) FROM users",Integer.class));assertEquals(0,sql.queryForObject("SELECT count(*) FROM stored_files",Integer.class));assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_orphan_file_observations",Integer.class));assertEquals(1,journal().orphanEntries().size());assertTrue(journal().entries().isEmpty());assertTrue(journal().fileEntries().isEmpty());
        var entry=journal().orphanEntries().getFirst();assertEquals(sha(BYTES),entry.sha256());assertEquals(BYTES.length,entry.bytes());assertNotNull(entry.confirmedAbsentAt());assertFalse(entry.confirmedAbsentAt().isBefore(entry.preparedAt()));assertNull(sql.queryForObject("SELECT actor_id FROM audit_logs WHERE action='orphan_file_erased' AND resource_id=?",UUID.class,file));app.getBean(PrivateFileStorage.class).put(file.toString(),BYTES);guard();guard();assertFalse(Files.exists(storage.resolve(file.toString())));assertTrue(app.getBean(PrivacyReadiness.class).ready());assertEquals(entry.preparedAt(),journal().orphanEntries().getFirst().preparedAt());assertEquals(entry.suppressionUntil(),journal().orphanEntries().getFirst().suppressionUntil());assertFalse(journal().orphanEntries().getFirst().confirmedAbsentAt().isBefore(entry.confirmedAbsentAt()));
    }
    @Test void changedContentRestartsTheObservationWindowInsteadOfUsingTheOldAge()throws Exception {
        UUID file=orphan();assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));age(file);byte[] changed=BYTES.clone();changed[changed.length-1]=33;Files.write(storage.resolve(file.toString()),changed);assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));assertEquals(PrivacyOrphanFileTransactions.Outcome.WAITING,tx().inspect(file));assertArrayEquals(changed,Files.readAllBytes(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());assertTrue(sql.queryForObject("SELECT first_seen_at>now()-interval '1 minute' FROM privacy_orphan_file_observations WHERE file_id=?",Boolean.class,file));
    }
    @Test void metadataCreatedAfterObservationAndSoftDeletedMetadataBothPreventOrphanClassification()throws Exception {
        var owner=owner();UUID file=orphan();assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));age(file);metadata(file,owner);assertEquals(PrivacyOrphanFileTransactions.Outcome.KNOWN,tx().inspect(file));assertArrayEquals(BYTES,app.getBean(FileService.class).download(owner,file).data());assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_orphan_file_observations WHERE file_id=?",Integer.class,file));sql.update("UPDATE stored_files SET deleted_at=now(),erasure_requested_at=now() WHERE id=?",file);assertEquals(PrivacyOrphanFileTransactions.Outcome.KNOWN,tx().inspect(file));assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());
    }
    @Test void aLegacyPreservationDiscoveredAfterSelectionProtectsUnknownOwnershipAndResetsTheAllowanceAfterRelease()throws Exception {
        var owner=owner();UUID file=orphan();tx().inspect(file);age(file);UUID hold=UUID.randomUUID();String cipher=app.getBean(PrivacyEvidenceCrypto.class).seal(PrivacyEvidenceCrypto.Field.HOLD_REASON,owner.id(),hold,"Synthetic legacy preservation requiring assisted ownership recovery");
        sql.update("INSERT INTO privacy_legal_holds(id,user_id,category,resource_type,resource_id,legal_basis,reason_ciphertext,created_by,review_at,expires_at) VALUES(?,?,'files','stored_file',?,'regular_exercise_of_rights',?,?,now()+interval '1 hour',now()+interval '1 day')",hold,owner.id(),file,cipher,owner.id());assertEquals(PrivacyOrphanFileTransactions.Outcome.HELD,tx().inspect(file));assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());sql.update("UPDATE privacy_legal_holds SET released_at=now() WHERE id=?",hold);assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file));assertEquals(PrivacyOrphanFileTransactions.Outcome.WAITING,tx().inspect(file));
    }
    @Test void aRealUploadOwnsItsFileLockUntilMetadataCommitsAndTheCollectorDoesNotWaitOnIt()throws Exception {
        var owner=owner();var controlled=app.getBean(TestStorage.class);var gate=new Gate(new CountDownLatch(1),new CountDownLatch(1),new AtomicReference<>());controlled.gate.set(gate);
        try(var executor=Executors.newVirtualThreadPerTaskExecutor()){
            var upload=executor.submit(()->app.getBean(FileService.class).upload(owner,"identity",BYTES));assertTrue(gate.entered().await(8,TimeUnit.SECONDS));UUID file=gate.file().get();assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,file));long start=System.nanoTime();assertEquals(PrivacyOrphanFileTransactions.Outcome.BUSY,tx().inspect(file));assertTrue(System.nanoTime()-start<TimeUnit.SECONDS.toNanos(2));assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());gate.release().countDown();assertEquals(file,upload.get(8,TimeUnit.SECONDS).id());assertEquals(PrivacyOrphanFileTransactions.Outcome.KNOWN,tx().inspect(file));assertArrayEquals(BYTES,app.getBean(FileService.class).download(owner,file).data());
        }finally{gate.release().countDown();controlled.gate.set(null);}
    }
    @Test void anExceptionAfterTheActualCommitDoesNotDeleteTheCommittedUpload()throws Exception {
        var owner=owner();var file=new AtomicReference<UUID>();assertThrows(IllegalStateException.class,()->app.getBean(TransactionTemplate.class).executeWithoutResult(status->{try{file.set(app.getBean(FileService.class).upload(owner,"identity",BYTES).id());}catch(IOException invalid){throw new java.io.UncheckedIOException(invalid);}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void afterCommit(){throw new IllegalStateException("Synthetic interruption after the actual upload commit");}});}));assertNotNull(file.get());assertTrue(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,file.get()));assertArrayEquals(BYTES,Files.readAllBytes(storage.resolve(file.get().toString())));assertEquals(PrivacyOrphanFileTransactions.Outcome.KNOWN,tx().inspect(file.get()));
    }
    @Test void aKnownRollbackCleansOnlyItsOwnNewBytesAndFailedCleanupCanBeRecoveredAsAnOrphan()throws Exception {
        var owner=owner();var file=new AtomicReference<UUID>();app.getBean(TransactionTemplate.class).executeWithoutResult(status->{try{file.set(app.getBean(FileService.class).upload(owner,"identity",BYTES).id());}catch(IOException invalid){throw new java.io.UncheckedIOException(invalid);}status.setRollbackOnly();});assertFalse(Files.exists(storage.resolve(file.get().toString())));assertFalse(sql.queryForObject("SELECT EXISTS(SELECT 1 FROM stored_files WHERE id=?)",Boolean.class,file.get()));
        var controlled=app.getBean(TestStorage.class);controlled.failErase.set(true);app.getBean(TransactionTemplate.class).executeWithoutResult(status->{try{file.set(app.getBean(FileService.class).upload(owner,"identity",BYTES).id());}catch(IOException invalid){throw new java.io.UncheckedIOException(invalid);}status.setRollbackOnly();});controlled.failErase.set(false);assertTrue(Files.exists(storage.resolve(file.get().toString())));assertEquals(PrivacyOrphanFileTransactions.Outcome.OBSERVED,tx().inspect(file.get()));age(file.get());assertEquals(PrivacyOrphanFileTransactions.Outcome.ERASED,tx().inspect(file.get()));assertFalse(Files.exists(storage.resolve(file.get().toString())));
    }
    @Test void failedPhysicalErasureKeepsTheInstructionAndBlocksReadinessUntilRetrySucceeds()throws Exception {
        UUID file=orphan();tx().inspect(file);age(file);var controlled=app.getBean(TestStorage.class);controlled.failErase.set(true);assertThrows(IOException.class,()->tx().inspect(file));assertEquals(1,journal().orphanEntries().size());assertNull(journal().orphanEntries().getFirst().confirmedAbsentAt());assertTrue(Files.exists(storage.resolve(file.toString())));assertThrows(Exception.class,this::guard);assertFalse(app.getBean(PrivacyReadiness.class).ready());controlled.failErase.set(false);guard();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertFalse(Files.exists(storage.resolve(file.toString())));assertNotNull(journal().orphanEntries().getFirst().confirmedAbsentAt());
    }
    @Test void conflictingBytesAndUnknownInventoryEntriesArePreservedInsteadOfSilentlyRemoved()throws Exception {
        UUID file=orphan();tx().inspect(file);age(file);Path note=Files.writeString(storage.resolve("operator-note.txt"),"Synthetic operator data");assertThrows(IOException.class,()->app.getBean(PrivacyOrphanFiles.class).runOnce(25,()->false));assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(Files.exists(note));assertTrue(journal().orphanEntries().isEmpty());Files.delete(note);assertEquals(PrivacyOrphanFileTransactions.Outcome.ERASED,tx().inspect(file));byte[] changed=BYTES.clone();changed[0]=33;app.getBean(PrivateFileStorage.class).put(file.toString(),changed);assertThrows(Exception.class,this::guard);assertFalse(app.getBean(PrivacyReadiness.class).ready());assertArrayEquals(changed,Files.readAllBytes(storage.resolve(file.toString())));Files.write(storage.resolve(file.toString()),BYTES);guard();assertFalse(Files.exists(storage.resolve(file.toString())));
    }
    @Test void staleObservationMetadataExpiresOnlyWhenTheFileIsGoneOrNowHasMetadata()throws Exception {
        var owner=owner();UUID missing=orphan(),known=orphan(),stillPresent=orphan();for(UUID file:List.of(missing,known,stillPresent)){tx().inspect(file);sql.update("UPDATE privacy_orphan_file_observations SET first_seen_at=now()-interval '9 days',last_seen_at=now()-interval '8 days' WHERE file_id=?",file);}Files.delete(storage.resolve(missing.toString()));metadata(known,owner);assertTrue(tx().pruneObservations(1)<=1);tx().pruneObservations(10);assertEquals(List.of(stillPresent),sql.query("SELECT file_id FROM privacy_orphan_file_observations",(r,n)->r.getObject(1,UUID.class)));assertTrue(Files.exists(storage.resolve(known.toString())));assertTrue(Files.exists(storage.resolve(stillPresent.toString())));
    }
    @Test void anIndependentPendingDecisionPreventsDestructiveWorkEvenIfAnotherProcessStillThinksItIsReady()throws Exception {
        UUID file=orphan();tx().inspect(file);age(file);app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{try{app.getBean(PrivacyHoldControlJournal.class).prepare(app.getBean(PrivacyRetentionSnapshot.class).capture());}catch(IOException invalid){throw new java.io.UncheckedIOException(invalid);}});assertTrue(app.getBean(PrivacyReadiness.class).ready());assertThrows(IOException.class,()->tx().inspect(file));assertFalse(app.getBean(PrivacyReadiness.class).ready());assertTrue(Files.exists(storage.resolve(file.toString())));assertTrue(journal().orphanEntries().isEmpty());assertTrue(app.getBean(PrivacyHoldControlJournal.class).pending().isPresent());
    }
    @Test void rolledBackDatabaseWorkCannotPublishAnAbsenceWitnessAndTheCompletionPassCanRepairIt()throws Exception {
        UUID file=orphan();tx().inspect(file);age(file);assertThrows(IllegalStateException.class,()->app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{try{assertEquals(PrivacyOrphanFileTransactions.Outcome.ERASED,tx().inspect(file));}catch(IOException unavailable){throw new java.io.UncheckedIOException(unavailable);}TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){@Override public void beforeCommit(boolean readOnly){throw new IllegalStateException("Synthetic database rollback after physical erasure");}});}));assertFalse(Files.exists(storage.resolve(file.toString())));var pending=journal().orphanEntries().getFirst();assertNull(pending.confirmedAbsentAt());assertEquals(0,sql.queryForObject("SELECT count(*) FROM audit_logs WHERE action='orphan_file_erased' AND resource_id=?",Integer.class,file));app.getBean(PrivacyOrphanFiles.class).runOnce(25,()->false);assertNotNull(journal().orphanEntries().getFirst().confirmedAbsentAt());assertEquals(0,sql.queryForObject("SELECT count(*) FROM privacy_orphan_file_observations WHERE file_id=?",Integer.class,file));assertEquals(pending.preparedAt(),journal().orphanEntries().getFirst().preparedAt());assertEquals(pending.suppressionUntil(),journal().orphanEntries().getFirst().suppressionUntil());
    }
    @Test void realOldArchiveReplaySuppressesBothAnOldPhotoLinkAndBytesWithoutAnyArchivedRowWhilePreservingTheLedger()throws Exception {
        var owner=owner();var image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);var imageBytes=new java.io.ByteArrayOutputStream();assertTrue(javax.imageio.ImageIO.write(image,"png",imageBytes));UUID linked=app.getBean(FileService.class).upload(owner,"photo",imageBytes.toByteArray()).id();byte[] linkedBytes=app.getBean(PrivateFileStorage.class).get(linked.toString());assertEquals("image/webp",sql.queryForObject("SELECT content_type FROM stored_files WHERE id=?",String.class,linked));
        app.getBean(TransactionTemplate.class).executeWithoutResult(ignored->{UUID clearing=sql.queryForObject("INSERT INTO ledger_accounts(kind) VALUES('provider_clearing') RETURNING id",UUID.class),credit=sql.queryForObject("INSERT INTO ledger_accounts(owner_id,kind) VALUES(?,'passenger_credit') RETURNING id",UUID.class,owner.id());UUID transaction=sql.queryForObject("INSERT INTO ledger_transactions(event_key,kind,reason,body_hash) VALUES(?,'synthetic_orphan_restore','Synthetic orphan restore preservation',?) RETURNING id",UUID.class,"orphan-proof:"+UUID.randomUUID(),"b".repeat(64));sql.update("INSERT INTO ledger_entries(transaction_id,account_id,cents) VALUES(?,?,-700),(?,?,700)",transaction,clearing,transaction,credit);});
        Path backup=temporary.resolve("before-orphan-discovery.dump");database.dumpDatabaseArchive(backup);sql.update("UPDATE users SET photo_file_id=NULL WHERE id=?",owner.id());sql.update("DELETE FROM stored_files WHERE id=?",linked);UUID unregistered=orphan();for(UUID file:List.of(linked,unregistered)){tx().inspect(file);age(file);assertEquals(PrivacyOrphanFileTransactions.Outcome.ERASED,tx().inspect(file));}assertEquals(2,journal().orphanEntries().size());app.close();app=null;database.resetSchema();database.restoreDatabaseArchive(backup);Files.write(storage.resolve(linked.toString()),linkedBytes);Files.write(storage.resolve(unregistered.toString()),BYTES);start();assertTrue(app.getBean(PrivacyReadiness.class).ready());assertFalse(Files.exists(storage.resolve(linked.toString())));assertFalse(Files.exists(storage.resolve(unregistered.toString())));assertNull(sql.queryForObject("SELECT photo_file_id FROM users WHERE id=?",UUID.class,owner.id()));assertEquals("active",sql.queryForObject("SELECT account_status FROM users WHERE id=?",String.class,owner.id()));assertEquals(700L,sql.queryForObject("SELECT sum(e.cents) FROM ledger_entries e JOIN ledger_accounts a ON a.id=e.account_id WHERE a.owner_id=? AND a.kind='passenger_credit'",Long.class,owner.id()));assertEquals(2,sql.queryForObject("SELECT count(*) FROM ledger_entries",Integer.class));assertEquals("FILE_NOT_FOUND",assertThrows(com.unicarona.shared.ApiException.class,()->app.getBean(FileService.class).download(owner,linked)).code());
    }
}
